mapper.select:
SELECT * FROM rag_chunks
WHERE document_id = #{documentId}
ORDER BY chunk_index ASC

SELECT c.id AS chunk_id, c.document_id, c.chunk_text, d.title, d.region, d.source_type, d.source_name, d.source_url, c.locator_json, c.index_version, 1 - (c.embedding_vector <=> #{queryVector,jdbcType=OTHER}::vector) AS vector_score, 0 AS bm25_score, 0 AS freshness_score FROM rag_chunks c JOIN rag_documents d ON d.id = c.document_id WHERE d.status = 'indexed' AND d.index_published = 1 AND c.embedding_vector IS NOT NULL
AND d.region = #{region}
ORDER BY c.embedding_vector <=> #{queryVector,jdbcType=OTHER}::vector ASC LIMIT #{limit}

SELECT c.id AS chunk_id, c.document_id, c.chunk_text, d.title, d.region, d.source_type, d.source_name, d.source_url, c.locator_json, c.index_version, 0 AS vector_score, ts_rank_cd(c.search_tsv, websearch_to_tsquery('simple', #{queryText})) AS bm25_score, 0 AS freshness_score FROM rag_chunks c JOIN rag_documents d ON d.id = c.document_id WHERE d.status = 'indexed' AND d.index_published = 1 AND c.search_tsv @@ websearch_to_tsquery('simple', #{queryText})
AND d.region = #{region}
ORDER BY bm25_score DESC LIMIT #{limit}

SELECT c.id AS chunk_id, c.document_id, c.chunk_text, d.title, d.region, d.source_type, d.source_name, d.source_url, c.locator_json, c.index_version, 0 AS vector_score, 1 AS bm25_score, 0 AS freshness_score FROM rag_chunks c JOIN rag_documents d ON d.id = c.document_id WHERE d.status = 'indexed' AND d.index_published = 1 AND (c.search_text LIKE CONCAT('%', #{queryText}, '%') OR c.chunk_text LIKE CONCAT('%', #{queryText}, '%') OR d.title LIKE CONCAT('%', #{queryText}, '%'))
AND d.region = #{region}
ORDER BY c.created_at DESC LIMIT #{limit}
